-- ============================================================
-- MCHRPSALA B419-1 a B419-114 (CONSOLIDADO): cambiar fecha + limpiar Bizlinks
-- Ejecutar desde servidor central (172.16.1.3)
-- Servidor MCHRPSALA: 10.20.0.132
--
-- B419-1 a B419-70:  faltaban en el motor, se re-actualizan a hoy
-- B419-71 a B419-114: estaban en el motor con fechas 1-3 nov
-- ============================================================

-- Actualizar FECHA_DOCUMENTO a hoy para TODO el rango 1-114
UPDATE [10.20.0.132].[soluflex_faro].[dbo].[CABECERA_DOCUMENTO]
SET FECHA_DOCUMENTO = CONVERT(char(8), GETDATE(), 112)
WHERE NUMERO_SERIE = 419
  AND NUMERO_DOCUMENTO BETWEEN 1 AND 114;

